std::vector<int64_t> fractional_shape(const at::Tensor& x,at::IntArrayRef kernel,at::IntArrayRef output,int64_t dimensions){TORCH_CHECK(x.dim()==dimensions+1||x.dim()==dimensions+2,"fractional_max_pool",dimensions,"d(): Expected ",dimensions+1,"D or ",dimensions+2,"D tensor");TORCH_CHECK(kernel.size()==dimensions&&output.size()==dimensions,"fractional pooling kernel_size and output_size have incorrect lengths");TORCH_CHECK(x.scalar_type()==at::kFloat&&can_pack_view(x),"Vulkan fractional pooling requires packable FP32 input");for(int64_t d=1;d<x.dim();d++)TORCH_CHECK(x.size(d)>0,"fractional pooling expected input to have non-zero size for non-batch dimensions");auto shape=x.sizes().vec();for(int64_t d=0;d<dimensions;d++){TORCH_CHECK(kernel[d]>0,"fractional pooling kernel size should be greater than zero");TORCH_CHECK(output[d]>=0,"fractional pooling output size must be non-negative");auto extent=x.size(x.dim()-dimensions+d);TORCH_CHECK(kernel[d]<=extent&&(dimensions==2?output[d]+kernel[d]-1<=extent:output[d]+kernel[d]-1<extent),"fractional pooling kernel too large relative to input");shape[x.dim()-dimensions+d]=output[d];}return shape;}
